function write_FormulaValue(value) {
	if (value == null) {
		var o = new_buf(8);
		o.write_shift(1, 3);
		o.write_shift(1, 0);
		o.write_shift(2, 0);
		o.write_shift(2, 0);
		o.write_shift(2, 65535);
		return o;
	} else if (typeof value == "number") return write_Xnum(value);
	return write_Xnum(0);
}
